import React, { useState } from 'react';

const QuanLyThongBaoCuDan = () => {
    const [activeTab, setActiveTab] = useState('chung');

    return (
        <div style={styles.container}>
            <div style={styles.header}>
                <h2 style={{color: '#2e7d32'}}>🔔 Trung tâm thông báo</h2>
                <p style={{color: '#666'}}>Cập nhật những tin tức mới nhất từ Ban quản lý</p>
            </div>

            <div style={styles.tabContainer}>
                <button onClick={() => setActiveTab('chung')} style={{...styles.tab, borderBottom: activeTab === 'chung' ? '3px solid #2e7d32' : 'none'}}>Bảng tin tòa nhà</button>
                <button onClick={() => setActiveTab('rieng')} style={{...styles.tab, borderBottom: activeTab === 'rieng' ? '3px solid #2e7d32' : 'none'}}>Phản hồi của tôi</button>
            </div>

            {activeTab === 'chung' ? (
                <div style={styles.newsCard}>
                    <span style={styles.newBadge}>MỚI</span>
                    <h4>Thông báo cắt nước bảo trì định kỳ</h4>
                    <p style={{fontSize: '12px', color: '#999'}}>17/04/2026</p>
                    <p>Để phục vụ bảo trì, tòa nhà sẽ tạm ngưng cấp nước từ 8h...</p>
                    <button style={{color: '#2e7d32', border: 'none', background: 'none', fontWeight: 'bold', cursor: 'pointer'}}>Xem chi tiết</button>
                </div>
            ) : (
                <div style={styles.formCard}>
                    <h3>Gửi ý kiến tới Admin</h3>
                    <textarea placeholder="Nhập phản hồi của bạn..." style={styles.textarea}></textarea>
                    <button style={styles.submitBtn}>Gửi phản hồi</button>
                </div>
            )}
        </div>
    );
};

const styles = {
    container: { width: '100%' },
    header: { marginBottom: '20px' },
    tabContainer: { display: 'flex', gap: '20px', borderBottom: '1px solid #ddd', marginBottom: '20px' },
    tab: { padding: '10px', background: 'none', border: 'none', cursor: 'pointer', fontWeight: 'bold' },
    newsCard: { padding: '20px', backgroundColor: '#fff', borderRadius: '15px', borderLeft: '5px solid #2e7d32', boxShadow: '0 2px 10px rgba(0,0,0,0.05)' },
    newBadge: { backgroundColor: '#ff4d4f', color: '#fff', padding: '2px 8px', borderRadius: '4px', fontSize: '10px' },
    formCard: { padding: '20px', backgroundColor: '#fff', borderRadius: '15px' },
    textarea: { width: '100%', height: '100px', padding: '10px', borderRadius: '8px', border: '1px solid #ddd', marginBottom: '10px' },
    submitBtn: { padding: '10px 20px', backgroundColor: '#2e7d32', color: '#fff', border: 'none', borderRadius: '8px', cursor: 'pointer' }
};

export default QuanLyThongBaoCuDan;
